    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'Which type of ultrasound transducer is most appropriate for visualizing the internal jugular vein during central line placement?', '["A low-frequency curvilinear probe", "A low-frequency phased array probe", "A high-frequency linear probe", "A transesophageal probe"]', 2, 'A high-frequency (e.g., 10-15 MHz) linear probe provides excellent superficial resolution, which is ideal for vascular access within 3-5 cm of the skin surface.'),
    (v_topic_id, 'When using Color Doppler on an ultrasound machine during vascular access, what do the colors red and blue represent?', '["Red is arterial blood, blue is venous blood", "Red is oxygenated blood, blue is deoxygenated blood", "Red is flow towards the probe, blue is flow away from the probe", "Red is high pressure, blue is low pressure"]', 2, 'BART: Blue Away, Red Towards. The colors represent direction of flow relative to the probe, NOT whether the vessel is an artery or a vein.'),
    (v_topic_id, 'Which view is generally preferred by novices for ultrasound-guided central line placement because it allows visualization of surrounding structures (like the carotid artery) adjacent to the vein?', '["Transverse (short-axis) view", "Longitudinal (in-plane or long-axis) view", "Coronal view", "Apical 4-chamber view"]', 0, 'The short-axis view allows the operator to see both the vein and the artery simultaneously, ensuring the needle remains over the vein. The long-axis view only shows one vessel at a time.'),
    (v_topic_id, 'When inserting a needle under ultrasound guidance in the short-axis (out-of-plane) view, how does the needle tip appear?', '["As a long white line", "As a brightly echogenic (white) dot", "As an anechoic (black) shadow", "As a comet-tail artifact"]', 1, 'Because the needle crosses the ultrasound beam perpendicularly, only a cross-section of the needle is visible, appearing as a bright white dot. The probe must be "slid" forward to keep the tip in view.'),
    (v_topic_id, 'Which artifact is commonly produced by a metallic needle or catheter under ultrasound, appearing as a series of parallel echogenic lines extending deep to the object?', '["Acoustic shadowing", "Acoustic enhancement", "Reverberation artifact", "Mirror image artifact"]', 2, 'Reverberation occurs when the ultrasound beam bounces back and forth between the probe and the highly reflective metallic needle, creating multiple false images (lines) deeper in the tissue.'),
    (v_topic_id, 'A patient with a right internal jugular central line develops a swollen face, distended neck veins, and upper extremity edema. The line has been in place for 3 weeks. What is the most likely diagnosis?', '["Heart failure", "Superior Vena Cava (SVC) Syndrome from catheter-associated thrombosis", "Anaphylaxis to the catheter material", "Air embolism"]', 1, 'Long-term central lines are a major risk factor for deep vein thrombosis in the upper extremities or SVC. Thrombosis can completely occlude the SVC, leading to SVC syndrome.'),
    (v_topic_id, 'If a newly placed central line cannot be flushed and cannot draw blood from one of its lumens, what is the most appropriate initial pharmacological intervention for suspected thrombosis?', '["Intravenous Heparin infusion", "Instilling Alteplase (tPA) into the blocked lumen (Cathflo lock)", "Intravenous Aspirin", "Flushing forcefully with a 10 mL syringe"]', 1, 'A small dose of tPA (Alteplase) can be instilled into the catheter and allowed to dwell (usually 30-120 mins) to dissolve the clot within the lumen without causing systemic fibrinolysis.'),
    (v_topic_id, 'During Central Venous Catheter (CVC) removal, the patient should be placed in the Trendelenburg position and instructed to hum or perform a Valsalva maneuver as the catheter is pulled. Why?', '["To prevent vagal-induced bradycardia", "To increase positive intrathoracic pressure and prevent a venous air embolism", "To decrease bleeding from the site", "To prevent a pneumothorax"]', 1, 'Holding breath, humming, or Valsalva increases intrathoracic pressure above atmospheric pressure, preventing air from being sucked into the open venous tract once the catheter is removed.'),
    (v_topic_id, 'A patient in the ICU is found to have a venous air embolism immediately after a central line is removed. They are in severe shock. In addition to placing them in the left lateral decubitus position, what immediate therapy should be started?', '["100% Oxygen via non-rebreather mask", "Intravenous Nitroglycerin", "Intravenous Heparin", "Continuous positive airway pressure (CPAP)"]', 0, '100% oxygen creates a diffusion gradient that helps reabsorb the nitrogen gas in the air bubble, shrinking the embolus faster.'),
    (v_topic_id, 'When drawing a diagnostic blood sample from a central line, what is the standard protocol to prevent dilution of the lab results with IV fluids or medications previously in the line?', '["Flush the line with 10 mL of heparin before drawing", "Draw the blood very slowly", "Discard the first 5 to 10 mL of blood drawn from the line", "Turn off all IV fluids for 2 hours before drawing"]', 2, 'Discarding the initial "waste" volume clears the dead space of the catheter and any residual fluid, ensuring the sample is pure, undiluted blood.'),
    (v_topic_id, 'A patient receiving Total Parenteral Nutrition (TPN) requires a blood transfusion and IV antibiotics. Why is a dedicated, single lumen of a multi-lumen central line exclusively reserved for TPN?', '["TPN corrodes the catheter material", "TPN has a high lipid and glucose content that is highly susceptible to infection and incompatible with many drugs/blood products", "TPN must be administered under high pressure", "TPN will cause blood to immediately hemolyze"]', 1, 'Opening the TPN line to draw blood or push other medications dramatically increases the risk of CRBSI and can cause dangerous precipitation with incompatible drugs.'),
    (v_topic_id, 'Which component of the "Central Line Bundle" has been proven most effective at reducing Catheter-Related Bloodstream Infections (CRBSIs)?', '["Changing the catheter over a wire every 3 days", "Using maximal sterile barrier precautions during insertion", "Applying prophylactic antibiotic ointment to the site daily", "Using the femoral site instead of the subclavian"]', 1, 'The central line bundle includes hand hygiene, maximal sterile barriers, chlorhexidine skin antisepsis, optimal site selection (avoiding femoral), and daily review of line necessity.'),
    (v_topic_id, 'You suspect a central line is infected (CRBSI). The patient has a fever of 39 C and no other source of infection. The line is no longer necessary for management. The most appropriate next step is:', '["Start oral antibiotics and leave the line", "Remove the central line and send the catheter tip for culture, along with drawing peripheral blood cultures", "Exchange the catheter over a guidewire", "Inject antibiotics directly into the catheter hub"]', 1, 'If the line is not strictly needed, it must be removed. The tip should be sent for semi-quantitative culture, and peripheral blood cultures are required to confirm bacteremia.'),
    (v_topic_id, 'The ideal site for placing a transvenous pacing wire or a pulmonary artery (Swan-Ganz) catheter is the:', '["Right Subclavian Vein", "Right Internal Jugular Vein", "Left Internal Jugular Vein", "Femoral Vein"]', 1, 'The Right IJ offers a straight, nearly vertical drop through the SVC directly into the right atrium, which makes floating specialized catheters much easier than navigating the angles from the left side or subclavian.'),
    (v_topic_id, 'What is the most common direction for an inadvertent catheter tip migration when a central line is inserted into the Subclavian Vein?', '["Down into the Inferior Vena Cava", "Across to the contralateral subclavian vein", "Upwards into the ipsilateral Internal Jugular Vein", "Into the right ventricle"]', 2, 'Because the subclavian vein meets the IJ at a right angle, the guidewire or catheter frequently passes the SVC and travels superiorly up the IJ into the neck.'),
    (v_topic_id, 'During an internal jugular central line placement, turning the patient''s head more than 45 degrees to the contralateral side is discouraged because:', '["It causes severe neck pain", "It increases the overlap between the internal jugular vein and the carotid artery, increasing the risk of through-and-through arterial puncture", "It compresses the internal jugular vein, making it smaller", "It causes the patient to swallow, moving the anatomy"]', 1, 'Excessive head rotation pulls the IJ directly over the top of the carotid artery. A rotation of only 15-30 degrees is optimal to keep the vein lateral to the artery.'),
    (v_topic_id, 'In the setting of a peripheral IV extravasation of a high-dose vasopressor (e.g., Norepinephrine), the skin becomes pale, cold, and ischemic. What is the pharmacological antidote injected subcutaneously around the site?', '["Epinephrine", "Phentolamine", "Atropine", "Protamine"]', 1, 'Phentolamine is an alpha-adrenergic antagonist. Injecting it locally causes vasodilation and restores blood flow, preventing severe tissue necrosis and amputation.'),
    (v_topic_id, 'Intraosseous (IO) access is contraindicated in which of the following situations?', '["A patient in cardiac arrest", "A patient with severe hypovolemic shock and collapsed veins", "A fractured bone or a bone with a prior IO attempt within the last 48 hours", "A patient who requires vasopressors"]', 2, 'Fluid injected into a fractured bone or a bone with a recent puncture hole will simply leak out of the defect into the surrounding tissue, causing compartment syndrome.'),
    (v_topic_id, 'Which of the following is the most feared and severe complication of unrecognized Intraosseous (IO) needle dislodgement and subsequent fluid extravasation?', '["Fat embolism", "Compartment syndrome of the limb", "Osteomyelitis", "Sepsis"]', 1, 'If the IO needle slips out of the marrow cavity or goes through the opposite cortex, massive fluid resuscitation will accumulate in the tight fascial compartments of the leg/arm, leading to compartment syndrome and limb loss.'),
    (v_topic_id, 'You place an Intraosseous (IO) line in a conscious, awake patient who is in hemorrhagic shock. When you attempt to flush the line with saline, the patient screams in agony. What is the standard practice to mitigate this pain?', '["Remove the IO and place a central line", "Administer slow push-dose intravenous Ketamine", "Slowly infuse 2% preservative-free Lidocaine into the IO space before flushing", "Dilute the saline with sterile water"]', 2, 'The medullary cavity is rich in pain receptors. Pushing fluids into it causes severe expansion pain. Preservative-free lidocaine (usually 40 mg) pushed slowly over 2 minutes numbs the cavity prior to the fluid flush.'),
    (v_topic_id, 'What is the maximum recommended dwell time for an Intraosseous (IO) catheter?', '["2 to 4 hours", "24 hours", "72 hours", "7 days"]', 1, 'IO lines are strictly temporary, life-saving bridges to definitive access. They must be removed within 24 hours (preferably much sooner) due to the escalating risk of osteomyelitis.'),
    (v_topic_id, 'In pediatric IO placement, the standard anatomical landmark for the proximal tibia is:', '["1-2 cm inferior and 1-2 cm medial to the tibial tuberosity", "Directly on the tibial tuberosity", "1-2 cm superior and lateral to the patella", "On the medial malleolus"]', 0, 'Because the tibial tuberosity is where the growth plate (physis) is located, the IO must be placed slightly inferior and medial to avoid damaging the growth plate in children.'),
    (v_topic_id, 'Which clinical sign reliably confirms successful placement of an Intraosseous (IO) needle?', '["The needle feels loose and wobbles easily", "Inability to aspirate any blood or marrow", "The needle stands firmly on its own at a 90-degree angle, and fluid flushes easily without soft tissue swelling", "The patient reports a sharp, burning pain in the chest"]', 2, 'A properly seated IO needle is firmly embedded in the bone cortex. It should stand upright without support, and fluid should flow freely without causing the calf to swell.'),
    (v_topic_id, 'An adult patient in severe shock requires an IO. You select the proximal humerus site. How should the patient''s arm be positioned for insertion?', '["Abducted 90 degrees", "Adducted, with the elbow flexed and the hand resting on the patient''s abdomen (internally rotated)", "Raised above the head", "Straight down by their side, palm facing up"]', 1, 'Adducting and internally rotating the arm exposes the greater tubercle of the humerus and rotates the bicipital groove (containing the biceps tendon) safely out of the way.'),
    (v_topic_id, 'A patient requires continuous invasive blood pressure monitoring and frequent arterial blood gas (ABG) draws. Which procedure is indicated?', '["Triple lumen central venous catheter", "Pulmonary artery catheter", "Peripheral arterial line (e.g., radial artery)", "Peripherally Inserted Central Catheter (PICC)"]', 2, 'An arterial line provides beat-to-beat continuous blood pressure monitoring and allows for painless, frequent ABG sampling without repeated arterial sticks.'),
    (v_topic_id, 'Prior to placing a radial arterial line, the Allen test is traditionally performed (though its clinical utility is debated). What is the purpose of the Allen test?', '["To assess for nerve damage in the hand", "To ensure adequate collateral blood flow to the hand via the ulnar artery in case the radial artery thromboses", "To confirm the patient has a normal blood pressure", "To locate the radial nerve"]', 1, 'The Allen test evaluates the patency of the palmar arch. If the radial artery becomes occluded by the catheter, the hand must survive on blood flow from the ulnar artery.'),
    (v_topic_id, 'When comparing the complication rates of different central line sites, which statement is true regarding Subclavian vein stenosis?', '["It is a rare complication and has no clinical consequence", "It frequently occurs after placement of large Subclavian dialysis catheters and can preclude the future use of that arm for an AV fistula", "It is only caused by PICC lines", "It requires immediate amputation"]', 1, 'Subclavian stenosis is a major, long-term complication of subclavian lines. It ruins the venous return for that arm, making it impossible for a vascular surgeon to place a hemodialysis fistula in that limb later.'),
    (v_topic_id, 'Under ultrasound, lung sliding is observed at the pleural line. What does the ABSENCE of lung sliding strongly suggest in a trauma patient?', '["Atelectasis", "Pneumothorax", "Hemothorax", "Pulmonary contusion"]', 1, 'Lung sliding represents the visceral pleura rubbing against the parietal pleura. In a pneumothorax, air separates the two layers, completely abolishing the sliding sign.'),
    (v_topic_id, 'When using M-mode (Motion mode) ultrasound to evaluate the lung, normal lung sliding produces a pattern known as the:', '["Barcode sign", "Stratosphere sign", "Seashore sign", "Target sign"]', 2, 'The "seashore sign" consists of straight horizontal lines above the pleura (representing stationary chest wall tissue) and grainy, sandy static below the pleura (representing the moving, aerated lung).'),
    (v_topic_id, 'When using M-mode ultrasound, the presence of a pneumothorax replaces the normal "seashore sign" with straight, horizontal lines throughout the entire image. This is known as the:', '["Stratosphere or Barcode sign", "Comet tail sign", "A-line sign", "B-line sign"]', 0, 'Without lung sliding, there is no motion below the pleural line. The ultrasound simply records stationary tissue everywhere, resulting in parallel lines resembling a barcode.'),
    (v_topic_id, 'You are placing a femoral central line. You identify the artery via palpation. Where is the femoral vein located in relation to the femoral nerve?', '["The vein is medial to the nerve", "The vein is lateral to the nerve", "The vein is anterior to the nerve", "The vein is superior to the nerve"]', 0, 'NAVEL (lateral to medial). The nerve is the most lateral structure, followed by the artery, then the vein is medial to both.'),
    (v_topic_id, 'A patient arrives in cardiac arrest. The team has been doing CPR for 2 minutes and cannot establish a peripheral IV. What is the absolute best next step for vascular access?', '["Perform a venous cutdown on the saphenous vein", "Attempt a Subclavian central line while CPR is ongoing", "Insert a proximal tibia Intraosseous (IO) line immediately", "Administer medications down the endotracheal tube"]', 2, 'Endotracheal drug administration is erratic and unpredictable. An IO line is the standard of care for immediate, reliable access in cardiac arrest when IV access fails.'),
    (v_topic_id, 'Which of the following describes the correct measurement of the depth of the right internal jugular vein to the cavoatrial junction using external landmarks?', '["From the insertion site, down to the ipsilateral nipple", "From the insertion site, down to the sternal angle (Angle of Louis), minus 2 cm", "It is always exactly 20 cm in every patient", "From the earlobe to the umbilicus"]', 1, 'The cavoatrial junction lies roughly at the level of the sternal angle (where the 2nd rib attaches). Measuring the catheter against the patient''s chest prior to insertion prevents advancing it into the heart.'),
    (v_topic_id, 'Which anatomical variation makes left-sided internal jugular central line placement inherently more difficult and riskier than right-sided placement?', '["The left IJ is usually half the size of the right IJ", "The left IJ requires two sharp turns (into the brachiocephalic vein, then the SVC) to reach the heart", "The left IJ has no valves", "The carotid artery on the left is lateral to the vein"]', 1, 'The right IJ is a straight vertical tube into the SVC. The left IJ must curve sharply medially to become the left brachiocephalic vein before crossing the chest to join the SVC.'),
    (v_topic_id, 'A patient has a Pulmonary Artery (Swan-Ganz) catheter in place. The balloon is inflated to obtain a Pulmonary Capillary Wedge Pressure (PCWP). What does the PCWP indirectly measure?', '["Right ventricular end-diastolic pressure", "Left atrial pressure (Left ventricular end-diastolic pressure)", "Systemic vascular resistance", "Pulmonary vascular resistance"]', 1, 'When the balloon wedges in a branch of the pulmonary artery, it creates a static column of blood extending through the pulmonary capillaries to the left atrium, estimating left-sided heart filling pressures.'),
    (v_topic_id, 'A patient in shock has a Central Venous Pressure (CVP) of 2 mmHg (Low). What is the most likely cause of their shock?', '["Cardiac tamponade", "Tension pneumothorax", "Hypovolemia or hemorrhage", "Massive pulmonary embolism"]', 2, 'A low CVP indicates empty venous capacitance vessels, hallmark for hypovolemic or hemorrhagic shock. Tamponade, tension pneumothorax, and PE all cause obstructive shock with profoundly elevated CVP.'),
    (v_topic_id, 'A patient with a central line has a CVP of 22 mmHg (High), hypotension, and muffled heart sounds. Ultrasound shows a large pericardial effusion. What is the expected physiological finding regarding right heart filling?', '["Increased venous return", "Compression of the right ventricle preventing diastolic filling", "Left ventricular hypertrophy", "Massive pulmonary edema"]', 1, 'This is cardiac tamponade. The high pressure in the pericardial sac compresses the low-pressure right ventricle, halting venous return (hence the high CVP) and causing obstructive shock.'),
    (v_topic_id, 'During a central line placement, the dilator is pushed forcefully and completely into the neck, "up to the hub." Why is this a dangerous error?', '["The dilator will become stuck and impossible to remove", "The dilator is very stiff and straight; pushing it deeply can easily puncture the back wall of the SVC or brachiocephalic vein", "It will cause an air embolism", "It will bend the guidewire"]', 1, 'The dilator is only meant to widen the skin and subcutaneous tissue track. It should only be inserted a few centimeters. Pushing a stiff dilator deep into the venous system causes catastrophic vascular perforation.'),
    (v_topic_id, 'Which of the following actions must be taken if you suspect you have placed a large-bore central venous catheter into the subclavian artery?', '["Pull the catheter immediately and place a sandbag on the chest", "Leave the catheter in place, do not use it, and immediately consult Vascular Surgery or Interventional Radiology", "Flush the catheter with heparin to keep the artery patent", "Connect the catheter to a pressure transducer and use it as an arterial line"]', 1, 'Pulling a large catheter from a non-compressible artery (subclavian) will result in a massive, uncontained hemothorax or neck hematoma. It must be removed surgically or with endovascular closure devices.'),
    (v_topic_id, 'What is the most definitive imaging modality to rule out a pneumothorax following the placement of a subclavian central venous catheter?', '["Supine portable chest X-ray", "Upright PA chest X-ray", "Ultrasound of the heart", "MRI of the chest"]', 1, 'While an upright PA chest X-ray is standard and effective, a supine X-ray often misses small pneumothoraces because air collects anteriorly, not apically. If an upright film isn''t possible, bedside ultrasound is actually more sensitive than a supine X-ray, but upright X-ray remains the classic gold standard for post-line clearance.'),
    (v_topic_id, 'A physician is attempting to place a right IJ central line. The patient is morbidly obese, breathing rapidly, and cannot lie flat. What is the most appropriate next step?', '["Proceed with the Right IJ attempt with the patient sitting at 45 degrees", "Administer a paralytic agent to force the patient to lie flat", "Switch to the femoral vein site", "Attempt a Subclavian line blindly"]', 2, 'If a patient cannot tolerate lying flat (Trendelenburg), placing an IJ or Subclavian line is dangerous (high risk of air embolism and poor distention). The femoral site allows the patient to sit up during placement.'),
    (v_topic_id, 'Which of the following describes the correct handling of the guidewire during the insertion of the central venous catheter over the wire?', '["Push the catheter all the way in, then look for the wire", "Hold the wire at the skin, slide the catheter over it until the wire protrudes from the hub of the catheter, GRASP the wire at the hub, then advance the catheter into the skin", "Pull the wire out halfway, then push the catheter in", "Lubricate the wire with lidocaine"]', 1, 'You must never advance the catheter into the skin until the wire is visible and physically grasped at the back (hub) of the catheter. This guarantees the wire cannot be pushed entirely into the patient (retained guidewire error).'),
    (v_topic_id, 'A "PICC line" is advantageous for patients requiring 6 weeks of IV antibiotics because:', '["It can be placed by a trained nurse, avoids the risks of pneumothorax, and carries a lower infection risk than a femoral line for long-term use", "It does not enter the central circulation", "It never causes DVT", "It has a larger lumen than a standard CVC"]', 0, 'PICC lines provide safe, long-term central access without the acute procedural risks (pneumothorax, arterial puncture) of neck/chest lines.'),
    (v_topic_id, 'Which of the following is a classic clinical presentation of a Catheter-Related Bloodstream Infection (CRBSI)?', '["Fever, chills, and purulent exudate at the insertion site without any other identifiable source of infection", "Chest pain radiating to the back", "Cough with purulent sputum", "Dysuria and hematuria"]', 0, 'Unexplained fever, particularly with erythema or pus at the line site, strongly points to a CRBSI.'),
    (v_topic_id, 'Which organism is the most common cause of Catheter-Related Bloodstream Infections (CRBSI)?', '["Escherichia coli", "Coagulase-negative Staphylococci (e.g., Staphylococcus epidermidis)", "Pseudomonas aeruginosa", "Streptococcus pneumoniae"]', 1, 'Skin flora, particularly Staphylococcus epidermidis and Staphylococcus aureus, are the most frequent culprits introduced during insertion or subsequent hub manipulation.'),
    (v_topic_id, 'You are evaluating a trauma patient. The ultrasound shows NO lung sliding on the right side. However, you also see "B-lines" (vertical, comet-tail artifacts) originating from the pleura on the right side. What does this mean?', '["The patient definitely has a pneumothorax", "The patient DOES NOT have a pneumothorax", "The patient has a hemothorax", "The ultrasound probe is broken"]', 1, 'B-lines are generated by fluid-filled interlobular septa in the lung. If you see B-lines, the visceral pleura MUST be pressed against the parietal pleura, absolutely ruling out a pneumothorax at that exact spot.'),
    (v_topic_id, 'During a central line placement, the physician utilizes a "longitudinal" (in-plane) ultrasound view. What is the primary risk associated with this view if the operator is not highly experienced?', '["It causes more pain", "The operator may mistakenly visualize a small slice of the artery instead of the vein, as the probe can easily slide laterally off the vein", "It cannot show the needle tip", "It increases the risk of air embolism"]', 1, 'Because the vessels run parallel and close to each other, a slight tilt of the probe can make the artery look like the vein in longitudinal view. Short-axis allows verification of both side-by-side.'),
    (v_topic_id, 'When using the Seldinger technique, what should you do immediately after removing the introducer needle, leaving only the guidewire in the vessel?', '["Advance the dilator", "Wipe the wire with alcohol", "Maintain constant, firm control of the guidewire with at least one hand at all times", "Apply a sterile dressing"]', 2, 'The wire is slippery and can easily be pulled into the venous system by cardiac motion or respiratory effort. It must never be released.'),
    (v_topic_id, 'A patient with an IO line in the right proximal tibia develops a swollen, tense, and pale right calf. The IO fluids are running at a wide-open rate. The patient has weak pedal pulses. What is the immediate treatment?', '["Administer IV antibiotics", "Stop the IO infusion immediately, remove the IO, and urgently consult surgery for suspected compartment syndrome", "Elevate the leg and apply ice", "Push more lidocaine into the IO"]', 1, 'Extravasation of pressurized fluid into the tight fascial compartments of the calf causes compartment syndrome, a surgical emergency requiring fasciotomy to save the limb.'),
    (v_topic_id, 'A central line is placed in the Right Subclavian vein. The post-procedure CXR shows the catheter tip pointing upwards and terminating in the Right Internal Jugular vein. What is the most appropriate management?', '["Leave it; it functions fine as a central line", "Administer tPA", "Under sterile conditions, withdraw the catheter a few centimeters, flush it, and potentially attempt to gently manipulate/re-wire it downward into the SVC, or remove and replace it", "Push it in deeper"]', 2, 'A catheter pointing up the IJ is not in the central circulation, will cause uncomfortable fluid administration to the head, and carries a high risk of thrombosis. It must be repositioned or replaced.');
